"""Score blind glyph readings after freezing both masked response files."""
import json
from collections import Counter, defaultdict
from pathlib import Path
import sys

work = Path(sys.argv[1])
rows = json.loads((work/'sealed-key.json').read_text())
readers = {name: json.loads((work/f'reader-{name}.json').read_text()) for name in ('a','b')}
for name,codes in readers.items():
    assert set(codes) == {row['tile'] for row in rows}, name
    assert all(code in {'A','B','C','D','U'} for code in codes.values()), name
for row in rows:
    row['reads'] = {name: codes[row['tile']] for name,codes in readers.items()}


def agreement(sample):
    paired = [(r['reads']['a'], r['reads']['b']) for r in sample]
    paired = [(a,b) for a,b in paired if a != 'U' and b != 'U']
    return {'trials': len(sample), 'both_readable': len(paired),
            'exact_agreement': sum(a==b for a,b in paired),
            'family_agreement': sum((a in 'ABC')==(b in 'ABC') for a,b in paired),
            'correct_including_unresolved': {name:sum(r['expected']==r['reads'][name] for r in sample) for name in readers},
            'confusion': {name:{expected:dict(Counter(r['reads'][name] for r in sample if r['expected']==expected))
                               for expected in 'ABCD' if any(r['expected']==expected for r in sample)} for name in readers}}


fresh = [row for row in rows if row['source']=='new']
by_pair = defaultdict(dict)
for row in fresh:
    by_pair[row['pair']][row['v101'][-1]] = row
pair_results = []
for pair, cases in by_pair.items():
    assert set(cases) == {'N','n'}
    labels = {}
    classes = {}
    for name in readers:
        upper,lower = (cases[c]['reads'][name] for c in ('N','n'))
        classes[name] = upper+lower
        if upper not in 'ABC' or lower not in 'ABC':
            labels[name] = 'unresolved'
        else:
            labels[name] = 'fewer' if upper<lower else 'more' if upper>lower else 'equal'
    pair_results.append({'pair':pair, 'hand':cases['N']['hand'], 'classes_N_then_n':classes,'relative':labels})

summary = {'all':agreement(rows),'new':agreement(fresh),'controls':agreement([r for r in rows if r['source']=='control']),
           'by_hand':{hand:agreement([r for r in fresh if r['hand']==hand]) for hand in ('1','2','3')},
           'relative':{name:dict(Counter(pair['relative'][name] for pair in pair_results)) for name in readers}}
print(json.dumps({'summary':summary,'pairs':pair_results,'trials':rows},indent=2))
